def apply_offline(packs: dict[str, dict[str, str]]) -> None:
    missing = [code for code in OFFLINE if code not in packs]
    extra = [code for code in packs if code not in OFFLINE]
    if missing or extra:
        raise SystemExit(f"indic offline missing={missing} extra={extra}")
    for code, text in OFFLINE.items():
        packs[code]["engineOffline"] = text
